import java.util.concurrent.*;

// ❌ OLD: Raw executor usage. If fetchB() throws, fetchA() is still
// running with no automatic cancellation — an orphaned task that can
// outlive the request. Also, waiting on two futures manually is
// verbose and error-prone.
public class FetchLegacy {
  String fetch() throws Exception {
    try (var e = Executors.newVirtualThreadPerTaskExecutor()) {
      Future<String> a = e.submit(() -> fetchA()); // ❌ OLD
      Future<String> b = e.submit(() -> fetchB()); // ❌ OLD
      // ❌ OLD: if fetchB throws, fetchA keeps running (leak);
      // cancel() is manual and easily forgotten.
      String ra = a.get();
      String rb = b.get();
      return ra + rb;
    }
  }
}

import java.util.concurrent.*;

// ✅ NEW: Structured scope. All child tasks are tied to the scope's
// lifetime; on the first failure, siblings are cancelled; close()
// throws if anything failed. No orphaned tasks.
public class FetchModern {
  String fetch() throws Exception {
    try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
      // ✅ NEW: fork both subtasks
      Future<String> a = scope.fork(() -> fetchA()); // ✅ NEW
      Future<String> b = scope.fork(() -> fetchB()); // ✅ NEW

      scope.join(); // ✅ NEW: wait for all (or shutdown on first failure)
      scope.throwIfFailed(); // ✅ NEW: propagate the first exception

      return a.resultNow() + b.resultNow(); // ✅ NEW: both succeeded
    } // ✅ NEW: scope.close() also cancels anything still running
  }
}
